import{_ as s,o as a,c as n,a4 as i}from"./chunks/framework.DHNVigYl.js";const g=JSON.parse('{"title":"Using with Node-RED","description":"","frontmatter":{},"headers":[],"relativePath":"use/node-red.md","filePath":"use/node-red.md","lastUpdated":1788361043000}'),t={name:"use/node-red.md"};function d(o,e,l,r,p,h){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="using-with-node-red" tabindex="-1">Using with Node-RED <a class="header-anchor" href="#using-with-node-red" aria-label="Permalink to &quot;Using with Node-RED&quot;">​</a></h1><p>The <code>node-red-contrib-theengs-decoder</code> package adds a <strong>theengs decode</strong> node to the Node-RED palette. Wire it after any node that produces BLE advertisement messages — for example an MQTT input from a Theengs Gateway, or a BLE-scanner node — and it will replace the raw advertisement on <code>msg.payload</code> with the decoded device information.</p><p>The decoder runs as WebAssembly, so installation does not require a C++ toolchain on the host running Node-RED.</p><h2 id="installing" tabindex="-1">Installing <a class="header-anchor" href="#installing" aria-label="Permalink to &quot;Installing&quot;">​</a></h2><p>From inside Node-RED, open the palette manager (☰ → Manage palette → Install) and search for <code>node-red-contrib-theengs-decoder</code>. Click <strong>Install</strong>.</p><p>Or from the command line in your Node-RED user directory (typically <code>~/.node-red</code>):</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node-red-contrib-theengs-decoder</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Then restart Node-RED.</p><h2 id="wiring-it-up" tabindex="-1">Wiring it up <a class="header-anchor" href="#wiring-it-up" aria-label="Permalink to &quot;Wiring it up&quot;">​</a></h2><p>The node accepts <code>msg.payload</code> as either an object or a JSON string with at least one of:</p><ul><li><code>servicedata</code> — hex string of the BLE service data</li><li><code>manufacturerdata</code> — hex string of the BLE manufacturer data</li><li><code>id</code> — device identifier (MAC), optional, used by some decoders</li><li><code>name</code> — advertised local name, optional, used by some decoders</li></ul><p>A typical flow looks like:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ MQTT in (BTtoMQTT/+) ] → [ theengs decode ] → [ debug ]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>When a decoder matches, <code>msg.payload</code> becomes an object with <code>brand</code>, <code>model</code>, <code>model_id</code>, and any device-specific readings (<code>tempc</code>, <code>hum</code>, <code>batt</code>, …).</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><ul><li><strong>Name</strong> — optional label shown in the editor.</li><li><strong>Pass through on no match</strong> — when checked (default), advertisements that no decoder recognizes are forwarded unchanged so the rest of your flow can still see them. When unchecked, unmatched messages are dropped.</li></ul><h2 id="example-flow" tabindex="-1">Example flow <a class="header-anchor" href="#example-flow" aria-label="Permalink to &quot;Example flow&quot;">​</a></h2><p>The package ships an importable example flow at <a href="https://github.com/theengs/decoder/blob/development/nodejs/node-red-contrib-theengs-decoder/examples/decode-flow.json" target="_blank" rel="noreferrer"><code>examples/decode-flow.json</code></a>. In Node-RED: ☰ → Import → paste the JSON → <strong>Import</strong>. Deploy, click the inject node, and the debug pane should show the decoded miflora reading.</p><h2 id="building-a-development-version" tabindex="-1">Building a development version <a class="header-anchor" href="#building-a-development-version" aria-label="Permalink to &quot;Building a development version&quot;">​</a></h2><p>The Node-RED node depends on the <a href="./nodejs.html"><code>theengs-decoder</code></a> base package. To work on both from a checkout, build the base package locally first:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --recursive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/theengs/decoder.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> decoder/nodejs/theengs-decoder</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../node-red-contrib-theengs-decoder</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-save</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../theengs-decoder</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>Then point Node-RED at the local checkout:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.node-red</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/decoder/nodejs/node-red-contrib-theengs-decoder</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div>`,23)])])}const k=s(t,[["render",d]]);export{g as __pageData,k as default};
